sites.find:
while (along < distance) {
    float alpha = (along - first) / span
        * fade
        * transition_alpha;
    if (primary->vy.type_id
        == PROJECTILE_TYPE_FIRE_BULLETS) {
        grim_interface_ptr->grim_set_color(
            1.0f, 0.6f, 0.1f, alpha);
    } else {
        grim_interface_ptr->grim_set_color(
            0.5f, 0.6f, 1.0f, alpha);
    }

